 frames[k]={'frames':len(hashes),'distinct_source_rgb_frames':len(set(hashes)),'max_identical_source_frame_run':best,'producer_hashes_match_frozen_source':frozen_ok,'clean_mp4_sha_matches_export':hashlib.sha256((R/row['final']).read_bytes()).hexdigest()==data['video_sha256'][row['final']]}
 root=np.array([d['pose']['root'] for d in states]);velocity=np.diff(root,axis=0)*30;acceleration=np.diff(velocity,axis=0)*30;motion[k]={'root_peak_speed_m_s':float(np.linalg.norm(velocity,axis=1).max()),'root_peak_finite_difference_acceleration_m_s2':float(np.linalg.norm(acceleration,axis=1).max()),'interpretation':'Measured kinematic motion, not force validation. Acting/jerk remains subject to playback review.'}
 assess[k]={'overall':'NEEDS REVIEW','user_approved':False,'bounded_geometry':qa[k]['geometry_status'],'foot_contact_measured':'PASS' if qa[k]['max_planted_toe_drift_m']<1e-6 else 'FAIL','hand_prop_surface_measured':'PASS' if qa[k]['independent_prop_surface_error_m']<.001 else 'FAIL','physical_weight_and_acting':'NEEDS REVIEW','silhouette_and_head_turn':'NEEDS REVIEW','camera_readability':'NEEDS REVIEW','all_volume_collision':'NEEDS REVIEW','sound_sync':'NOT TESTED — silent motion proof'}
